# test-setup-pywinpty.ps1 -- tests for scripts/setup-pywinpty.ps1 (dev path) and its
# MDM copy (deploy/setup-pywinpty.ps1 generated by build-deploy.sh, pin embedded).
#
# Cases (each with its own APPDATA -- the pip --user target is %APPDATA%\Python --,
# HOME, log dir and summary file; one pip cache for the suite):
#   a  dry run (-DryRun, AITOOLS_DRY_RUN=1): OK "dry-run: would install <ver>",
#      no pip install, no winpty in the APPDATA user site
#   b  install into an empty APPDATA (real PyPI download, python3 on PATH):
#      OK "<ver> (installed)"; python3 imports winpty <ver> from that APPDATA
#   c  re-run on b's APPDATA: OK "<ver> (verified)", no "Running:" pip line
#   d  AITOOLS_PYWINPTY_PIN set to a missing file: exit 1, ERROR "pin file missing"
#   e  AITOOLS_PYWINPTY_PYTHON set to a missing interpreter: exit 0,
#      WARN "python not found" + ACTION
#   f  a fake interpreter (a .ps1 that answers the script's -c probes; pwsh runs it
#      in-process through `& $Python @Arguments`): externally managed, venv, an
#      uncovered tag (cp399), pip refusing (externally-managed-environment), pip
#      failing, and pip succeeding without an importable winpty -- each with its
#      summary rows, and no pip call where the script must refuse
#   g  MDM copy: build-deploy.sh (Git Bash, temp HOME, fixture dotprofile, stub
#      pwsh validator) generates deploy/setup-pywinpty.ps1; copied alone into an
#      empty dir, -DryRun gives the dry-run row and "Pin: embedded in this script",
#      a real run into a fresh APPDATA gives "<ver> (installed)" (pip -r on the
#      temp copy of the embedded pin; the suite's pip cache saves the download)
# a, b, c and g's runs need python3 to be a CPython the pin covers, neither a venv
# nor EXTERNALLY-MANAGED: otherwise they are SKIP with the reason (FAIL under
# CI=true, where the windows job provides one).
#
# Safe to re-run: never reads or writes the real APPDATA, HOME or dotprofile (a temp
# root, removed on exit). Needs network for b. Platform: Windows (pwsh 7);
# setup-pywinpty.ps1 is Windows-guarded, so on macOS/Linux the suite prints one
# SKIP line and exits 0 (CI runs it on the windows job only,
# plans/ci-platform-targeting.md). Exit 1 if any case fails.
#
# Usage: pwsh -NoProfile -File tests/pywinpty/test-setup-pywinpty.ps1 [-Help]

param([switch]$Help)
if ($Help) { Get-Content $PSCommandPath -TotalCount 34 | Select-Object -Skip 1; exit 0 }

if (-not $IsWindows) {
    Write-Output "SKIP test-setup-pywinpty.ps1 -- setup-pywinpty.ps1 is Windows-guarded; on macOS/Linux tests/pywinpty/test-setup-pywinpty.sh covers setup-pywinpty.sh"
    Write-Output ""
    Write-Output "0 passed, 0 failed, 1 skipped"
    exit 0
}

$ErrorActionPreference = "Stop"
$suiteStart = Get-Date
$root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$setup = Join-Path $root "scripts\setup-pywinpty.ps1"
$pin = Join-Path $root "scripts\requirements-pywinpty.txt"
$tmpRoot = Join-Path ([IO.Path]::GetTempPath()) ("pywinpty-test-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $tmpRoot | Out-Null
$pwshExe = (Get-Process -Id $PID).Path
$pipCache = Join-Path $tmpRoot "pipcache"
$onCI = ($env:CI -eq "true")

$script:pass = 0; $script:fail = 0; $script:skip = 0
$script:C = $null

function Check([string]$Name, [bool]$Cond) {
    if ($Cond) { Write-Output "PASS $Name"; $script:pass++ }
    else {
        Write-Output "FAIL $Name"; $script:fail++
        if ($script:C) {
            foreach ($f in @("summary", "out")) {
                $p = Join-Path $script:C $f
                if (Test-Path -LiteralPath $p) {
                    Write-Output "      | -- $f"
                    (Get-Content -LiteralPath $p -Tail 15) | ForEach-Object { Write-Output ("      | " + ($_ -replace "`e\[[0-9;]*m", "")) }
                }
            }
        }
    }
}
function Skip([string]$Name, [string]$Reason) {
    if ($onCI) { Write-Output "FAIL $Name -- $Reason (not allowed under CI)"; $script:fail++ }
    else { Write-Output "SKIP $Name -- $Reason"; $script:skip++ }
}

# Pinned version and covered tags, from the pin itself
$pinText = [IO.File]::ReadAllText($pin)
$pinVer = if ($pinText -match '(?m)^\s*pywinpty==([0-9][0-9A-Za-z.]*)') { $Matches[1] } else { $null }
$pinTags = if ($pinText -match '(?m)^\s*#\s*wheel-tags:\s*(.+?)\s*$') { @($Matches[1] -split '\s+') } else { @() }
if (-not $pinVer -or $pinTags.Count -eq 0) { Write-Output "FAIL cannot read version/wheel tags from $pin"; exit 1 }

# Run-Setup <name> <script> [args] [-Env @{}] [-AppData dir] [-Cwd dir]: run the script
# in a child pwsh with the case's environment; returns the case dir.
function Run-Setup {
    param([string]$Name, [string]$ScriptPath, [string[]]$ScriptArgs = @(), [hashtable]$Env = @{}, [string]$AppData = "", [string]$Cwd = "")
    $c = Join-Path $tmpRoot $Name
    $script:C = $c
    foreach ($d in @("home", "logs")) { New-Item -ItemType Directory -Path (Join-Path $c $d) -Force | Out-Null }
    if (-not $AppData) { $AppData = Join-Path $c "appdata" }
    New-Item -ItemType Directory -Path $AppData -Force | Out-Null
    if (-not $Cwd) { $Cwd = $c }
    $vars = @{
        APPDATA = $AppData; HOME = (Join-Path $c "home"); USERPROFILE = (Join-Path $c "home")
        AITOOLS_LOG_DIR = (Join-Path $c "logs"); AITOOLS_SUMMARY_FILE = (Join-Path $c "summary")
        PIP_CACHE_DIR = $pipCache; PYTHONUSERBASE = $null; PYTHONNOUSERSITE = $null; PIP_CONFIG_FILE = $null
        AITOOLS_DRY_RUN = $null; AITOOLS_PYWINPTY_PIN = $null; AITOOLS_PYWINPTY_PYTHON = $null
    }
    foreach ($k in $Env.Keys) { $vars[$k] = $Env[$k] }
    [IO.File]::WriteAllText($vars.AITOOLS_SUMMARY_FILE, "")
    $saved = @{}
    foreach ($k in $vars.Keys) { $saved[$k] = [Environment]::GetEnvironmentVariable($k); [Environment]::SetEnvironmentVariable($k, $vars[$k]) }
    Push-Location -LiteralPath $Cwd
    try {
        $null | & $pwshExe -NoProfile -NonInteractive -File $ScriptPath @ScriptArgs *> (Join-Path $c "out")
        [IO.File]::WriteAllText((Join-Path $c "rc"), "$LASTEXITCODE")
    } finally {
        Pop-Location
        foreach ($k in $saved.Keys) { [Environment]::SetEnvironmentVariable($k, $saved[$k]) }
    }
    return $c
}
function Rc($c) { [IO.File]::ReadAllText((Join-Path $c "rc")).Trim() }
function Rows($c) { @([IO.File]::ReadAllLines((Join-Path $c "summary")) | ForEach-Object { $_.TrimEnd("`r") } | Where-Object { $_ }) }
function LogText($c) { $p = Join-Path $c "logs\deploy.log"; if (Test-Path -LiteralPath $p) { [IO.File]::ReadAllText($p) } else { "" } }
function HasRow($c, [string]$Row) { (Rows $c) -contains $Row }
function RowLike($c, [string]$Pattern) { [bool](@(Rows $c) | Where-Object { $_ -match $Pattern }) }
function WinptyIn([string]$AppData) { [bool](Get-ChildItem -LiteralPath $AppData -Recurse -Directory -Filter "winpty" -ErrorAction SilentlyContinue | Select-Object -First 1) }

# --- Is python3 usable for the real cases (a, b, c, g)? -------------------------
$probe = "import sys, os, sysconfig; print('tag=cp%d%d' % sys.version_info[:2] + ('t' if sysconfig.get_config_var('Py_GIL_DISABLED') else '') + '-' + sysconfig.get_platform().replace('-', '_').replace('.', '_')); print('venv=' + str(sys.prefix != sys.base_prefix)); print('em=' + str(os.path.isfile(os.path.join(sysconfig.get_path('stdlib'), 'EXTERNALLY-MANAGED')))); print('exe=' + sys.executable)"
$pyReason = $null
$py3 = Get-Command python3 -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
# Get-Command exempt: command-existence check; $null selects the SKIP reason below
if (-not $py3) { $pyReason = "python3 is not on PATH" }
else {
    $pi = @{}
    $lines = @(& $py3.Source -c $probe 2>&1)
    if ($LASTEXITCODE -ne 0) { $pyReason = "python3 ($($py3.Source)) does not run (exit $LASTEXITCODE)" }
    else {
        foreach ($l in $lines) { if ("$l" -match '^([a-z]+)=(.*)$') { $pi[$Matches[1]] = $Matches[2].Trim() } }
        if ($pi.venv -eq "True") { $pyReason = "python3 ($($pi.exe)) is a venv" }
        elseif ($pi.em -eq "True") { $pyReason = "python3 ($($pi.exe)) is EXTERNALLY-MANAGED" }
        elseif ($pinTags -notcontains $pi.tag) { $pyReason = "python3 ($($pi.exe)) is $($pi.tag), not covered by the pin" }
    }
}
if (-not $pyReason) { Write-Output "python3: $($pi.exe) ($($pi.tag)); pinned pywinpty $pinVer" }

try {
    # --- a: dry run --------------------------------------------------------------
    if ($pyReason) {
        Skip "a dry run (-DryRun, AITOOLS_DRY_RUN=1)" $pyReason
    } else {
        $c = Run-Setup -Name "a-dryrun" -ScriptPath $setup -ScriptArgs @("-DryRun")
        Check "a -DryRun: exit 0" ((Rc $c) -eq "0")
        Check "a -DryRun: one row 'OK|pywinpty|dry-run: would install $pinVer'" ((@(Rows $c) -join "`n") -ceq "OK|pywinpty|dry-run: would install $pinVer")
        Check "a -DryRun: pip command logged, not run" ((LogText $c).Contains("[DRY RUN] Would run: ") -and -not (LogText $c).Contains("Running: "))
        Check "a -DryRun: no winpty in the APPDATA user site" (-not (WinptyIn (Join-Path $c "appdata")))
        $c = Run-Setup -Name "a-envdry" -ScriptPath $setup -Env @{ AITOOLS_DRY_RUN = "1" }
        Check "a AITOOLS_DRY_RUN=1: exit 0, one row 'OK|pywinpty|dry-run: would install $pinVer'" ((Rc $c) -eq "0" -and (@(Rows $c) -join "`n") -ceq "OK|pywinpty|dry-run: would install $pinVer")
        Check "a AITOOLS_DRY_RUN=1: no pip install, no winpty in the APPDATA user site" (-not (LogText $c).Contains("Running: ") -and -not (WinptyIn (Join-Path $c "appdata")))
    }

    # --- b, c: install, then verified ------------------------------------------------
    $bAppData = Join-Path $tmpRoot "b-appdata"
    if ($pyReason) {
        Skip "b install into an empty APPDATA" $pyReason
        Skip "c re-run: verified" $pyReason
    } else {
        $t0 = Get-Date
        $c = Run-Setup -Name "b-install" -ScriptPath $setup -AppData $bAppData
        $bSecs = [int]((Get-Date) - $t0).TotalSeconds
        Check "b install: exit 0 ($bSecs s)" ((Rc $c) -eq "0")
        Check "b install: one row 'OK|pywinpty|$pinVer (installed)'" ((@(Rows $c) -join "`n") -ceq "OK|pywinpty|$pinVer (installed)")
        Check "b install: pip ran --user --only-binary=:all: --require-hashes with the repo pin" ((LogText $c) -match [regex]::Escape("-m pip install --user --only-binary=:all: --require-hashes --disable-pip-version-check --no-input -r $pin"))
        Check "b install: winpty landed in the temp APPDATA user site" (WinptyIn $bAppData)
        $savedAppData = $env:APPDATA
        $env:APPDATA = $bAppData
        try {
            $imp = @(& $py3.Source -c "import sys; sys.path[:] = [p for p in sys.path if p not in ('', '.')]; import importlib.metadata as m, winpty; print(m.version('pywinpty')); print(winpty.__file__)" 2>&1)
            $impRc = $LASTEXITCODE
        } finally { $env:APPDATA = $savedAppData }
        Check "b install: python3 imports winpty $pinVer from the temp APPDATA" ($impRc -eq 0 -and "$($imp[0])".Trim() -eq $pinVer -and "$($imp[1])".StartsWith($bAppData, [StringComparison]::OrdinalIgnoreCase))

        $c = Run-Setup -Name "c-rerun" -ScriptPath $setup -AppData $bAppData
        Check "c re-run: exit 0, one row 'OK|pywinpty|$pinVer (verified)'" ((Rc $c) -eq "0" -and (@(Rows $c) -join "`n") -ceq "OK|pywinpty|$pinVer (verified)")
        Check "c re-run: no 'Running:' pip line" (-not (LogText $c).Contains("Running: "))
    }

    # --- d: pin missing ------------------------------------------------------------
    $c = Run-Setup -Name "d-pin-missing" -ScriptPath $setup -Env @{ AITOOLS_PYWINPTY_PIN = (Join-Path $tmpRoot "no-such-pin.txt") }
    Check "d pin missing: exit 1, one row 'ERROR|pywinpty|pin file missing'" ((Rc $c) -eq "1" -and (@(Rows $c) -join "`n") -ceq "ERROR|pywinpty|pin file missing")
    Check "d pin missing: error names AITOOLS_PYWINPTY_PIN" ((LogText $c).Contains("AITOOLS_PYWINPTY_PIN is set but the file does not exist"))

    # --- e: no python --------------------------------------------------------------
    $c = Run-Setup -Name "e-no-python" -ScriptPath $setup -Env @{ AITOOLS_PYWINPTY_PYTHON = (Join-Path $tmpRoot "no-such\python.exe") }
    Check "e no python: exit 0" ((Rc $c) -eq "0")
    Check "e no python: rows WARN 'python not found' + ACTION 'Run aitools install (Step 15 Python) ...'" ((HasRow $c "WARN|pywinpty|python not found") -and (RowLike $c '^ACTION\|\|Run aitools install \(Step 15 Python\), then re-run ') -and (Rows $c).Count -eq 2)

    # --- f: fake interpreter -------------------------------------------------------
    # Answers the script's three -c calls (run check, probe, import check) from
    # FAKE_PY_* variables; a pip call is appended to FAKE_PY_CALLS and answered
    # with FAKE_PY_PIP_RC / FAKE_PY_PIP_OUT.
    $fake = Join-Path $tmpRoot "fake-python.ps1"
    [IO.File]::WriteAllText($fake, @'
$joined = $args -join ' '
if ($args[0] -eq '-m' -and $args[1] -eq 'pip') {
    [IO.File]::AppendAllText($env:FAKE_PY_CALLS, "pip $joined`n")
    if ($env:FAKE_PY_PIP_OUT) { Write-Output $env:FAKE_PY_PIP_OUT }
    exit ([int]$env:FAKE_PY_PIP_RC)
}
$code = "$($args[1])"
if ($code -match 'externally_managed') {
    Write-Output 'version=3.12.7'
    Write-Output 'majmin=3.12'
    Write-Output "executable=$PSCommandPath"
    Write-Output "tag=$env:FAKE_PY_TAG"
    Write-Output "venv=$env:FAKE_PY_VENV"
    Write-Output "externally_managed=$env:FAKE_PY_EM"
    Write-Output "user_site=$env:FAKE_PY_USER_SITE"
    Write-Output 'user_site_enabled=True'
    exit 0
}
if ($code -match 'winpty') {
    Write-Output "ModuleNotFoundError: No module named 'winpty'"
    exit 1
}
if ($code -match 'sys\.version') { Write-Output '3.12.7'; exit 0 }
Write-Output "fake-python: unexpected arguments: $joined"
exit 3
'@)

    # (PowerShell names are case-insensitive: the parameter must not be called $Fake)
    function Run-Fake([string]$Name, [hashtable]$Over) {
        $calls = Join-Path $tmpRoot "$Name.calls"
        [IO.File]::WriteAllText($calls, "")
        $e = @{
            AITOOLS_PYWINPTY_PYTHON = $fake; FAKE_PY_CALLS = $calls; FAKE_PY_TAG = "cp312-win_amd64"; FAKE_PY_VENV = "False"; FAKE_PY_EM = "False"
            FAKE_PY_USER_SITE = (Join-Path $tmpRoot "$Name\appdata\Python\Python312\site-packages"); FAKE_PY_PIP_RC = "0"; FAKE_PY_PIP_OUT = ""
        }
        foreach ($k in $Over.Keys) { $e[$k] = $Over[$k] }
        $c = Run-Setup -Name $Name -ScriptPath $setup -Env $e
        foreach ($k in $e.Keys) { if ($k -like "FAKE_PY_*") { [Environment]::SetEnvironmentVariable($k, $null) } }
        return $c
    }
    function PipCalls([string]$Name) { @([IO.File]::ReadAllLines((Join-Path $tmpRoot "$Name.calls")) | Where-Object { $_ }).Count }

    $c = Run-Fake "f-em" @{ FAKE_PY_EM = "True" }
    Check "f fake externally managed: exit 0" ((Rc $c) -eq "0")
    Check "f fake externally managed: rows WARN 'python externally managed' + ACTION naming AITOOLS_PYWINPTY_PYTHON" ((HasRow $c "WARN|pywinpty|python externally managed") -and (RowLike $c '^ACTION\|\|Run once with a non-managed CPython 3\.12 .*AITOOLS_PYWINPTY_PYTHON') -and (Rows $c).Count -eq 2)
    Check "f fake externally managed: the fake interpreter was used, no pip call" ((LogText $c).Contains("Interpreter: AITOOLS_PYWINPTY_PYTHON -> $fake") -and (PipCalls "f-em") -eq 0 -and -not (LogText $c).Contains("Running: "))

    $c = Run-Fake "f-venv" @{ FAKE_PY_VENV = "True" }
    Check "f fake venv: exit 0, rows WARN 'venv python, --user refused' + ACTION, no pip call" ((Rc $c) -eq "0" -and (HasRow $c "WARN|pywinpty|venv python, --user refused") -and (RowLike $c '^ACTION\|\|Deactivate the virtual environment') -and (Rows $c).Count -eq 2 -and (PipCalls "f-venv") -eq 0)

    $c = Run-Fake "f-tag" @{ FAKE_PY_TAG = "cp399-win_amd64" }
    Check "f fake uncovered tag: exit 0, rows WARN 'no wheel for cp399-win_amd64' + ACTION, no pip call" ((Rc $c) -eq "0" -and (HasRow $c "WARN|pywinpty|no wheel for cp399-win_amd64") -and (RowLike $c '^ACTION\|\|Python 3\.12\.7 \(cp399-win_amd64\) has no pinned pywinpty wheel') -and (Rows $c).Count -eq 2 -and (PipCalls "f-tag") -eq 0)

    $c = Run-Fake "f-pip-em" @{ FAKE_PY_PIP_RC = "1"; FAKE_PY_PIP_OUT = "error: externally-managed-environment" }
    Check "f fake pip refuses (externally-managed-environment): exit 0, WARN 'python externally managed' + ACTION, one pip call" ((Rc $c) -eq "0" -and (HasRow $c "WARN|pywinpty|python externally managed") -and (RowLike $c '^ACTION\|\|Run once with a non-managed CPython') -and (PipCalls "f-pip-em") -eq 1)

    $c = Run-Fake "f-pip-fail" @{ FAKE_PY_PIP_RC = "2"; FAKE_PY_PIP_OUT = "ERROR: THESE PACKAGES DO NOT MATCH THE HASHES" }
    Check "f fake pip fails: exit 1, one row 'ERROR|pywinpty|pip install failed (exit 2)'" ((Rc $c) -eq "1" -and (@(Rows $c) -join "`n") -ceq "ERROR|pywinpty|pip install failed (exit 2)")

    $c = Run-Fake "f-noimport" @{ FAKE_PY_PIP_OUT = "Successfully installed pywinpty-$pinVer" }
    Check "f fake pip ok, import fails: exit 1, one row 'ERROR|pywinpty|import failed after install'" ((Rc $c) -eq "1" -and (@(Rows $c) -join "`n") -ceq "ERROR|pywinpty|import failed after install" -and (PipCalls "f-noimport") -eq 1)

    # --- g: MDM copy ---------------------------------------------------------------
    # Git Bash (not the WSL bash.exe shim): AITOOLS_TEST_BASH, else next to git.
    $bash = $null
    if ($env:AITOOLS_TEST_BASH -and (Test-Path -LiteralPath $env:AITOOLS_TEST_BASH -PathType Leaf)) { $bash = $env:AITOOLS_TEST_BASH }
    else {
        $git = Get-Command git -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
        # Get-Command exempt: command-existence check; the candidates below are tested
        $cands = @()
        if ($git) { $gitRoot = Split-Path -Parent (Split-Path -Parent $git.Source); $cands += (Join-Path $gitRoot "bin\bash.exe"); $cands += (Join-Path $gitRoot "usr\bin\bash.exe") }
        $cands += (Join-Path $env:ProgramFiles "Git\bin\bash.exe")
        $bash = $cands | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1
    }
    if (-not $bash) {
        Skip "g MDM copy (build + runs)" "Git Bash not found (AITOOLS_TEST_BASH, next to git, Program Files\Git): build-deploy.sh needs it"
    } else {
        $g = Join-Path $tmpRoot "g-build"
        $dot = Join-Path $g "dot"
        foreach ($d in @("home\.aitools\logs", "bin", "dot")) { New-Item -ItemType Directory -Path (Join-Path $g $d) -Force | Out-Null }
        [IO.File]::WriteAllText((Join-Path $g "bin\pwsh"), "#!/usr/bin/env bash`nexit 0`n")
        [IO.File]::WriteAllText((Join-Path $dot ".gitignore"), ".scratch/`n*.bak.*`n")
        [IO.File]::WriteAllText((Join-Path $dot "README.md"), "# fixture`n")
        & git -C $dot init -q
        & git -C $dot -c user.email=test@example.invalid -c user.name=test -c core.autocrlf=false add -A
        & git -C $dot -c user.email=test@example.invalid -c user.name=test -c core.autocrlf=false commit -q -m fixture
        $fwd = { param($p) $p -replace '\\', '/' }
        $bv = @{
            HOME = (& $fwd (Join-Path $g "home")); USERPROFILE = (Join-Path $g "home"); AITOOLS_LOG_DIR = (& $fwd (Join-Path $g "home\.aitools\logs"))
            AITOOLS_USER_REPO_PATH = (& $fwd $dot); AITOOLS_SUMMARY_FILE = $null; AITOOLS_PROFILE_FILE = $null; AITOOLS_MACHINE_ALIAS = $null
            PATH = (Join-Path $g "bin") + [IO.Path]::PathSeparator + $env:PATH
        }
        $saved = @{}
        foreach ($k in $bv.Keys) { $saved[$k] = [Environment]::GetEnvironmentVariable($k); [Environment]::SetEnvironmentVariable($k, $bv[$k]) }
        $script:C = $g
        $t0 = Get-Date
        try {
            $null | & $bash (& $fwd (Join-Path $root "scripts\build-deploy.sh")) *> (Join-Path $g "out")
            $buildRc = $LASTEXITCODE
        } finally {
            foreach ($k in $saved.Keys) { [Environment]::SetEnvironmentVariable($k, $saved[$k]) }
        }
        $gSecs = [int]((Get-Date) - $t0).TotalSeconds
        $gen = Join-Path $dot "deploy\setup-pywinpty.ps1"
        Check "g build-deploy.sh (Git Bash $bash): exit 0, deploy/setup-pywinpty.ps1 generated ($gSecs s)" ($buildRc -eq 0 -and (Test-Path -LiteralPath $gen))
        if ((Test-Path -LiteralPath $gen) -and -not $pyReason) {
            $mdmBin = Join-Path $tmpRoot "g-mdm-bin"
            New-Item -ItemType Directory -Path $mdmBin | Out-Null
            Copy-Item -LiteralPath $gen -Destination $mdmBin
            $mdm = Join-Path $mdmBin "setup-pywinpty.ps1"
            Check "g MDM copy: alone in its directory (no pin file, no library beside it)" (@(Get-ChildItem -LiteralPath $mdmBin).Count -eq 1)

            $c = Run-Setup -Name "g-mdm-dryrun" -ScriptPath $mdm -ScriptArgs @("-DryRun") -Cwd $mdmBin
            Check "g MDM -DryRun: exit 0, one row 'OK|pywinpty|dry-run: would install $pinVer'" ((Rc $c) -eq "0" -and (@(Rows $c) -join "`n") -ceq "OK|pywinpty|dry-run: would install $pinVer")
            Check "g MDM -DryRun: log 'Pin: embedded in this script', no pip install" ((LogText $c).Contains("Pin: embedded in this script") -and -not (LogText $c).Contains("Running: ") -and -not (WinptyIn (Join-Path $c "appdata")))

            $c = Run-Setup -Name "g-mdm-install" -ScriptPath $mdm -Cwd $mdmBin
            Check "g MDM install (fresh APPDATA, pip cache from b): exit 0, one row 'OK|pywinpty|$pinVer (installed)'" ((Rc $c) -eq "0" -and (@(Rows $c) -join "`n") -ceq "OK|pywinpty|$pinVer (installed)")
            Check "g MDM install: pip -r on the temp copy of the embedded pin, temp pin removed" ((LogText $c).Contains("Pin: embedded in this script (written to ") -and (LogText $c).Contains("Removed temp pin ") -and (WinptyIn (Join-Path $c "appdata")))
        } elseif (Test-Path -LiteralPath $gen) {
            Skip "g MDM copy runs (-DryRun, install)" $pyReason
        }
    }
} finally {
    Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $tmpRoot) { Write-Output "warning: could not remove $tmpRoot" }
}

$secs = [int]((Get-Date) - $suiteStart).TotalSeconds
Write-Output ""
Write-Output "$($script:pass) passed, $($script:fail) failed, $($script:skip) skipped (windows, $secs s)"
if ($script:fail -gt 0) { exit 1 }
exit 0
